  var QUOTE_SUPPRESS_STORAGE_KEY = 'swai.quoteControl.noquotes.v1';

  function quoteControlParam() {
    var value = null;
    try {
      var query = new URLSearchParams(window.location.search || '');
      if (query.has('noquotes')) value = query.get('noquotes');
      else {
        var hashText = String(window.location.hash || '').replace(/^#/, '');
        var hash = new URLSearchParams(hashText);
        if (hash.has('noquotes')) value = hash.get('noquotes');
      }
    } catch (_) {}
    return value;
  }

  function syncQuoteControlFromUrl() {
    var value = quoteControlParam();
    if (value === null) return;
    var normalized = String(value == null ? '' : value).trim().toLowerCase();
    var disabled = !(normalized === '0' || normalized === 'false' || normalized === 'off' || normalized === 'no');
    try {
      if (window.sessionStorage) {
        if (disabled) sessionStorage.setItem(QUOTE_SUPPRESS_STORAGE_KEY, '1');
        else sessionStorage.removeItem(QUOTE_SUPPRESS_STORAGE_KEY);
      }
    } catch (_) {}
  }

  function quotesDisabled() {
    syncQuoteControlFromUrl();
    try { return !!(window.sessionStorage && sessionStorage.getItem(QUOTE_SUPPRESS_STORAGE_KEY) === '1'); }
    catch (_) { return false; }
  }

  window.SWAI_QUOTE_CONTROL = window.SWAI_QUOTE_CONTROL || {};
  window.SWAI_QUOTE_CONTROL.isDisabled = quotesDisabled;

  var QUOTE_DURATION_MS = 4000;
