  var INTERNATIONAL_DAYS = {"01-04":[{"en":"World Braille Day","el":"Παγκόσμια Ημέρα Μπράιγ","whyEn":"Braille gives blind and partially sighted people greater independence in reading, learning and daily life.","whyEl":"Η γραφή Μπράιγ ενισχύει την αυτονομία των τυφλών και των ατόμων με προβλήματα όρασης στην ανάγνωση, τη μάθηση και την καθημερινότητα."}],"01-24":[{"en":"International Day of Education","el":"Διεθνής Ημέρα Εκπαίδευσης","whyEn":"Quality education opens opportunities and helps reduce poverty and inequality.","whyEl":"Η ποιοτική εκπαίδευση δημιουργεί ευκαιρίες και συμβάλλει στη μείωση της φτώχειας και των ανισοτήτων."}],"01-26":[{"en":"International Day of Clean Energy","el":"Διεθνής Ημέρα Καθαρής Ενέργειας","whyEn":"Cleaner energy can reduce pollution and expand access to reliable electricity.","whyEl":"Η καθαρότερη ενέργεια μπορεί να μειώσει τη ρύπανση και να διευρύνει την πρόσβαση σε αξιόπιστο ηλεκτρισμό."}],"01-27":[{"en":"International Holocaust Remembrance Day","el":"Διεθνής Ημέρα Μνήμης του Ολοκαυτώματος","whyEn":"Remembering Holocaust victims helps confront antisemitism, hatred and denial.","whyEl":"Η μνήμη των θυμάτων του Ολοκαυτώματος συμβάλλει στην αντιμετώπιση του αντισημιτισμού, του μίσους και της άρνησης της ιστορίας."}],"02-02":[{"en":"World Wetlands Day","el":"Παγκόσμια Ημέρα Υγροτόπων","whyEn":"Wetlands protect biodiversity, filter water and help shield communities from floods.","whyEl":"Οι υγρότοποι προστατεύουν τη βιοποικιλότητα, καθαρίζουν το νερό και συμβάλλουν στην προστασία από πλημμύρες."}],"02-04":[{"en":"International Day of Human Fraternity","el":"Διεθνής Ημέρα Ανθρώπινης Αδελφοσύνης","whyEn":"Respect across religions and beliefs helps communities live together peacefully.","whyEl":"Ο σεβασμός ανάμεσα σε θρησκείες και πεποιθήσεις βοηθά τις κοινωνίες να συνυπάρχουν ειρηνικά."}],"02-06":[{"en":"International Day of Zero Tolerance to Female Genital Mutilation","el":"Διεθνής Ημέρα Μηδενικής Ανοχής στον Ακρωτηριασμό Γυναικείων Γεννητικών Οργάνων","whyEn":"Ending this harmful practice protects bodily autonomy, health and the rights of girls.","whyEl":"Η εξάλειψη αυτής της επιβλαβούς πρακτικής προστατεύει τη σωματική αυτονομία, την υγεία και τα δικαιώματα των κοριτσιών."}],"02-10":[{"en":"World Pulses Day","el":"Παγκόσμια Ημέρα Οσπρίων","whyEn":"Beans, lentils and other pulses offer affordable nutrition and can support sustainable farming.","whyEl":"Τα φασόλια, οι φακές και τα άλλα όσπρια προσφέρουν προσιτή διατροφή και μπορούν να στηρίξουν τη βιώσιμη γεωργία."}],"02-11":[{"en":"International Day of Women and Girls in Science","el":"Διεθνής Ημέρα Γυναικών και Κοριτσιών στην Επιστήμη","whyEn":"Equal opportunities in science help unlock talent and produce better solutions for everyone.","whyEl":"Οι ίσες ευκαιρίες στην επιστήμη αξιοποιούν περισσότερα ταλέντα και οδηγούν σε καλύτερες λύσεις για όλους."}],"02-13":[{"en":"World Radio Day","el":"Παγκόσμια Ημέρα Ραδιοφώνου","whyEn":"Radio reaches communities with news, education and emergency information, even where internet access is limited.","whyEl":"Το ραδιόφωνο προσφέρει ενημέρωση, εκπαίδευση και πληροφορίες έκτακτης ανάγκης, ακόμη και χωρίς εύκολη πρόσβαση στο διαδίκτυο."}],"02-20":[{"en":"World Day of Social Justice","el":"Παγκόσμια Ημέρα Κοινωνικής Δικαιοσύνης","whyEn":"Fair opportunities and decent work make societies more inclusive and resilient.","whyEl":"Οι δίκαιες ευκαιρίες και η αξιοπρεπής εργασία δημιουργούν κοινωνίες με περισσότερη συμμετοχή και ανθεκτικότητα."}],"02-21":[{"en":"International Mother Language Day","el":"Διεθνής Ημέρα Μητρικής Γλώσσας","whyEn":"Every language carries knowledge and identity; protecting linguistic diversity helps cultures thrive.","whyEl":"Κάθε γλώσσα μεταφέρει γνώση και ταυτότητα· η γλωσσική ποικιλία βοηθά τους πολιτισμούς να διατηρούνται ζωντανοί."}],"03-01":[{"en":"Zero Discrimination Day","el":"Ημέρα Μηδενικών Διακρίσεων","whyEn":"People deserve dignity and fair treatment regardless of who they are.","whyEl":"Κάθε άνθρωπος αξίζει αξιοπρέπεια και δίκαιη μεταχείριση, ανεξάρτητα από την ταυτότητά του."}],"03-03":[{"en":"World Wildlife Day","el":"Παγκόσμια Ημέρα Άγριας Ζωής","whyEn":"Protecting wild species also protects ecosystems that people depend on.","whyEl":"Η προστασία της άγριας ζωής διαφυλάσσει και τα οικοσυστήματα από τα οποία εξαρτόμαστε."}],"03-08":[{"en":"International Women's Day","el":"Παγκόσμια Ημέρα της Γυναίκας","whyEn":"Gender equality strengthens rights, opportunities and participation across society.","whyEl":"Η ισότητα των φύλων ενισχύει τα δικαιώματα, τις ευκαιρίες και τη συμμετοχή στην κοινωνία."}],"03-10":[{"en":"International Day of Women Judges","el":"Διεθνής Ημέρα Γυναικών Δικαστών","whyEn":"A more representative judiciary helps strengthen equality and trust in justice.","whyEl":"Μια δικαιοσύνη με ισότιμη εκπροσώπηση μπορεί να ενισχύσει την ισότητα και την εμπιστοσύνη."}],"03-15":[{"en":"International Day to Combat Islamophobia","el":"Διεθνής Ημέρα Καταπολέμησης της Ισλαμοφοβίας","whyEn":"Challenging prejudice and hostility helps protect freedom of belief and equal rights.","whyEl":"Η αντιμετώπιση της προκατάληψης και της εχθρότητας προστατεύει την ελευθερία θρησκείας και τα ίσα δικαιώματα."}],"03-20":[{"en":"International Day of Happiness","el":"Διεθνής Ημέρα Ευτυχίας","whyEn":"Well-being matters alongside economic growth when measuring how societies are doing.","whyEl":"Η ευημερία μετρά εξίσου με την οικονομική ανάπτυξη όταν αξιολογούμε την πρόοδο μιας κοινωνίας."}],"03-21":[{"en":"International Day for the Elimination of Racial Discrimination","el":"Διεθνής Ημέρα Εξάλειψης των Φυλετικών Διακρίσεων","whyEn":"Combating racism helps ensure that rights and opportunities are shared equally.","whyEl":"Η καταπολέμηση του ρατσισμού βοηθά να μοιράζονται ισότιμα τα δικαιώματα και οι ευκαιρίες."},{"en":"International Day of Forests","el":"Διεθνής Ημέρα Δασών","whyEn":"Forests shelter wildlife, store carbon and sustain water cycles.","whyEl":"Τα δάση φιλοξενούν άγρια ζωή, αποθηκεύουν άνθρακα και στηρίζουν τον κύκλο του νερού."}],"03-22":[{"en":"World Water Day","el":"Παγκόσμια Ημέρα Νερού","whyEn":"Safe water is essential for health, dignity and sustainable communities.","whyEl":"Το ασφαλές νερό είναι απαραίτητο για την υγεία, την αξιοπρέπεια και τις βιώσιμες κοινωνίες."}],"03-24":[{"en":"World Tuberculosis Day","el":"Παγκόσμια Ημέρα Φυματίωσης","whyEn":"Early diagnosis and access to treatment can prevent suffering and deaths from tuberculosis.","whyEl":"Η έγκαιρη διάγνωση και η πρόσβαση στη θεραπεία μπορούν να αποτρέψουν ασθένεια και θανάτους από φυματίωση."}],"03-25":[{"en":"International Day of Remembrance of the Victims of Slavery and the Transatlantic Slave Trade","el":"Διεθνής Ημέρα Μνήμης των Θυμάτων της Δουλείας και του Διατλαντικού Εμπορίου Σκλάβων","whyEn":"Remembering the slave trade honors victims and confronts its enduring legacy of racism.","whyEl":"Η μνήμη του δουλεμπορίου τιμά τα θύματα και μας καλεί να αντιμετωπίσουμε τη συνεχιζόμενη κληρονομιά του ρατσισμού."}],"03-30":[{"en":"International Day of Zero Waste","el":"Διεθνής Ημέρα Μηδενικών Αποβλήτων","whyEn":"Reducing, reusing and repairing things saves resources and limits pollution.","whyEl":"Η μείωση, η επαναχρησιμοποίηση και η επισκευή αντικειμένων εξοικονομούν πόρους και περιορίζουν τη ρύπανση."}],"04-02":[{"en":"World Autism Awareness Day","el":"Παγκόσμια Ημέρα Ενημέρωσης για τον Αυτισμό","whyEn":"Acceptance and accessibility help autistic people participate fully in society.","whyEl":"Η αποδοχή και η προσβασιμότητα βοηθούν τα αυτιστικά άτομα να συμμετέχουν ισότιμα στην κοινωνία."}],"04-04":[{"en":"International Day for Mine Awareness","el":"Διεθνής Ημέρα Ενημέρωσης για τις Νάρκες","whyEn":"Landmines can harm civilians long after fighting ends; clearing them saves lives.","whyEl":"Οι νάρκες απειλούν αμάχους πολύ μετά το τέλος των συγκρούσεων· η απομάκρυνσή τους σώζει ζωές."}],"04-06":[{"en":"International Day of Sport for Development and Peace","el":"Διεθνής Ημέρα Αθλητισμού για την Ανάπτυξη και την Ειρήνη","whyEn":"Sport can connect communities, support health and teach cooperation.","whyEl":"Ο αθλητισμός ενώνει κοινότητες, στηρίζει την υγεία και καλλιεργεί τη συνεργασία."}],"04-07":[{"en":"World Health Day","el":"Παγκόσμια Ημέρα Υγείας","whyEn":"Health systems and prevention make a real difference to everyone's quality of life.","whyEl":"Τα συστήματα υγείας και η πρόληψη κάνουν ουσιαστική διαφορά στην ποιότητα ζωής όλων."}],"04-12":[{"en":"International Day of Human Space Flight","el":"Διεθνής Ημέρα Πτήσης του Ανθρώπου στο Διάστημα","whyEn":"Space exploration expands scientific knowledge and reminds us of our shared planet.","whyEl":"Η εξερεύνηση του διαστήματος διευρύνει τη γνώση και μας θυμίζει τον κοινό μας πλανήτη."}],"04-21":[{"en":"World Creativity and Innovation Day","el":"Παγκόσμια Ημέρα Δημιουργικότητας και Καινοτομίας","whyEn":"New ideas can improve everyday life and help solve complex challenges.","whyEl":"Οι νέες ιδέες βελτιώνουν την καθημερινότητα και βοηθούν στην αντιμετώπιση σύνθετων προκλήσεων."}],"04-22":[{"en":"International Mother Earth Day","el":"Διεθνής Ημέρα Μητέρας Γης","whyEn":"Healthy ecosystems are the foundation of our health, food and future.","whyEl":"Τα υγιή οικοσυστήματα αποτελούν θεμέλιο της υγείας, της διατροφής και του μέλλοντός μας."}],"04-23":[{"en":"World Book and Copyright Day","el":"Παγκόσμια Ημέρα Βιβλίου και Πνευματικών Δικαιωμάτων","whyEn":"Books share ideas across cultures, while authors' rights support creative work.","whyEl":"Τα βιβλία μεταφέρουν ιδέες ανάμεσα στους πολιτισμούς, ενώ τα πνευματικά δικαιώματα στηρίζουν τους δημιουργούς."}],"04-25":[{"en":"World Malaria Day","el":"Παγκόσμια Ημέρα Ελονοσίας","whyEn":"Prevention, testing and treatment are vital to defeating a preventable disease.","whyEl":"Η πρόληψη, ο έλεγχος και η θεραπεία είναι καθοριστικά για την αντιμετώπιση μιας ασθένειας που μπορεί να προληφθεί."}],"04-26":[{"en":"International Chernobyl Disaster Remembrance Day","el":"Διεθνής Ημέρα Μνήμης της Καταστροφής του Τσερνόμπιλ","whyEn":"Remembering the disaster highlights long-term health, environmental and safety responsibilities.","whyEl":"Η μνήμη της καταστροφής υπενθυμίζει τις μακροχρόνιες ευθύνες για την υγεία, το περιβάλλον και την ασφάλεια."}],"04-28":[{"en":"World Day for Safety and Health at Work","el":"Παγκόσμια Ημέρα Ασφάλειας και Υγείας στην Εργασία","whyEn":"Safe workplaces prevent avoidable injuries and protect workers' well-being.","whyEl":"Οι ασφαλείς χώροι εργασίας αποτρέπουν τραυματισμούς και προστατεύουν την ευημερία των εργαζομένων."}],"04-30":[{"en":"International Jazz Day","el":"Διεθνής Ημέρα Τζαζ","whyEn":"Jazz celebrates creativity, improvisation and cultural exchange across borders.","whyEl":"Η τζαζ γιορτάζει τη δημιουργικότητα, τον αυτοσχεδιασμό και την πολιτιστική ανταλλαγή."}],"05-02":[{"en":"World Tuna Day","el":"Παγκόσμια Ημέρα Τόνου","whyEn":"Sustainable fishing helps conserve tuna populations and marine livelihoods.","whyEl":"Η βιώσιμη αλιεία προστατεύει τους πληθυσμούς τόνου και τις κοινότητες που ζουν από τη θάλασσα."}],"05-03":[{"en":"World Press Freedom Day","el":"Παγκόσμια Ημέρα Ελευθερίας του Τύπου","whyEn":"Independent journalism helps people make informed decisions and hold power accountable.","whyEl":"Η ανεξάρτητη δημοσιογραφία βοηθά τους πολίτες να ενημερώνονται και να ελέγχουν την εξουσία."}],"05-05":[{"en":"World Portuguese Language Day","el":"Παγκόσμια Ημέρα Πορτογαλικής Γλώσσας","whyEn":"Shared languages connect communities and preserve diverse cultural traditions.","whyEl":"Οι κοινές γλώσσες συνδέουν κοινωνίες και διαφυλάσσουν ποικίλες πολιτιστικές παραδόσεις."}],"05-12":[{"en":"International Day of Plant Health","el":"Διεθνής Ημέρα Υγείας των Φυτών","whyEn":"Healthy plants are vital for food security, ecosystems and rural economies.","whyEl":"Τα υγιή φυτά είναι απαραίτητα για την επισιτιστική ασφάλεια, τα οικοσυστήματα και την αγροτική οικονομία."}],"05-15":[{"en":"International Day of Families","el":"Διεθνής Ημέρα Οικογένειας","whyEn":"Supportive families and care networks help people through every stage of life.","whyEl":"Οι υποστηρικτικές οικογένειες και τα δίκτυα φροντίδας βοηθούν τους ανθρώπους σε κάθε στάδιο ζωής."}],"05-16":[{"en":"International Day of Light","el":"Διεθνής Ημέρα Φωτός","whyEn":"Light makes possible advances in science, medicine, communication and art.","whyEl":"Το φως επιτρέπει σημαντικές εξελίξεις στην επιστήμη, την ιατρική, την επικοινωνία και την τέχνη."}],"05-17":[{"en":"World Telecommunication and Information Society Day","el":"Παγκόσμια Ημέρα Τηλεπικοινωνιών και Κοινωνίας της Πληροφορίας","whyEn":"Digital connectivity can widen access to education, services and opportunity.","whyEl":"Η ψηφιακή συνδεσιμότητα διευρύνει την πρόσβαση στην εκπαίδευση, στις υπηρεσίες και στις ευκαιρίες."}],"05-20":[{"en":"World Bee Day","el":"Παγκόσμια Ημέρα Μέλισσας","whyEn":"Bees and other pollinators support crops, wild plants and biodiversity.","whyEl":"Οι μέλισσες και άλλοι επικονιαστές στηρίζουν τις καλλιέργειες, τα άγρια φυτά και τη βιοποικιλότητα."}],"05-21":[{"en":"World Day for Cultural Diversity for Dialogue and Development","el":"Παγκόσμια Ημέρα Πολιτισμικής Ποικιλομορφίας","whyEn":"Learning about other cultures strengthens respect and helps people live together.","whyEl":"Η γνωριμία με άλλους πολιτισμούς ενισχύει τον σεβασμό και τη συνύπαρξη."}],"05-22":[{"en":"International Day for Biological Diversity","el":"Διεθνής Ημέρα Βιοποικιλότητας","whyEn":"Biodiversity sustains food, medicine, clean water and resilient ecosystems.","whyEl":"Η βιοποικιλότητα στηρίζει τη διατροφή, την ιατρική, το καθαρό νερό και ανθεκτικά οικοσυστήματα."}],"05-29":[{"en":"International Day of UN Peacekeepers","el":"Διεθνής Ημέρα Κυανόκρανων του ΟΗΕ","whyEn":"Peacekeepers help protect civilians and support communities affected by conflict.","whyEl":"Οι ειρηνευτικές αποστολές συμβάλλουν στην προστασία των αμάχων και στη στήριξη κοινοτήτων που πλήττονται από συγκρούσεις."}],"05-31":[{"en":"World No Tobacco Day","el":"Παγκόσμια Ημέρα κατά του Καπνίσματος","whyEn":"Reducing tobacco use prevents disease and protects people from second-hand smoke.","whyEl":"Η μείωση του καπνίσματος προλαμβάνει ασθένειες και προστατεύει από το παθητικό κάπνισμα."}],"06-01":[{"en":"Global Day of Parents","el":"Παγκόσμια Ημέρα Γονέων","whyEn":"Parenting and caregiving deserve recognition and practical support.","whyEl":"Η ανατροφή των παιδιών και η φροντίδα αξίζουν αναγνώριση και ουσιαστική στήριξη."}],"06-03":[{"en":"World Bicycle Day","el":"Παγκόσμια Ημέρα Ποδηλάτου","whyEn":"Cycling can improve health, reduce emissions and make streets more livable.","whyEl":"Το ποδήλατο ενισχύει την υγεία, μειώνει τις εκπομπές και κάνει τις πόλεις πιο ανθρώπινες."}],"06-05":[{"en":"World Environment Day","el":"Παγκόσμια Ημέρα Περιβάλλοντος","whyEn":"Environmental protection safeguards the air, water, land and nature we depend on.","whyEl":"Η προστασία του περιβάλλοντος διαφυλάσσει τον αέρα, το νερό, τη γη και τη φύση που χρειαζόμαστε."}],"06-07":[{"en":"World Food Safety Day","el":"Παγκόσμια Ημέρα Ασφάλειας Τροφίμων","whyEn":"Safer food prevents illness and builds trust throughout the food chain.","whyEl":"Τα ασφαλή τρόφιμα προλαμβάνουν ασθένειες και ενισχύουν την εμπιστοσύνη στην αλυσίδα τροφίμων."}],"06-08":[{"en":"World Oceans Day","el":"Παγκόσμια Ημέρα Ωκεανών","whyEn":"Healthy oceans regulate climate, support marine life and provide livelihoods.","whyEl":"Οι υγιείς ωκεανοί ρυθμίζουν το κλίμα, φιλοξενούν θαλάσσια ζωή και στηρίζουν επαγγέλματα."}],"06-11":[{"en":"International Day of Play","el":"Διεθνής Ημέρα Παιχνιδιού","whyEn":"Play helps children learn, build relationships and develop creativity.","whyEl":"Το παιχνίδι βοηθά τα παιδιά να μαθαίνουν, να δημιουργούν σχέσεις και να αναπτύσσουν τη φαντασία τους."}],"06-12":[{"en":"World Day Against Child Labour","el":"Παγκόσμια Ημέρα κατά της Παιδικής Εργασίας","whyEn":"Children need safety and education rather than dangerous or exploitative work.","whyEl":"Τα παιδιά χρειάζονται ασφάλεια και εκπαίδευση, όχι επικίνδυνη ή εκμεταλλευτική εργασία."}],"06-14":[{"en":"World Blood Donor Day","el":"Παγκόσμια Ημέρα Εθελοντή Αιμοδότη","whyEn":"Voluntary blood donation supports emergency care and lifesaving treatment.","whyEl":"Η εθελοντική αιμοδοσία στηρίζει την επείγουσα περίθαλψη και θεραπείες που σώζουν ζωές."}],"06-15":[{"en":"World Elder Abuse Awareness Day","el":"Παγκόσμια Ημέρα Ευαισθητοποίησης για την Κακοποίηση Ηλικιωμένων","whyEn":"Older people deserve safety, respect and freedom from neglect or abuse.","whyEl":"Οι ηλικιωμένοι δικαιούνται ασφάλεια, σεβασμό και προστασία από παραμέληση και κακοποίηση."}],"06-17":[{"en":"World Day to Combat Desertification and Drought","el":"Παγκόσμια Ημέρα κατά της Ερημοποίησης και της Ξηρασίας","whyEn":"Protecting soil and water helps communities face drought and climate pressures.","whyEl":"Η προστασία του εδάφους και του νερού βοηθά τις κοινωνίες να αντιμετωπίζουν την ξηρασία και τις κλιματικές πιέσεις."}],"06-18":[{"en":"International Day for Countering Hate Speech","el":"Διεθνής Ημέρα Καταπολέμησης της Ρητορικής Μίσους","whyEn":"Challenging hateful language helps prevent discrimination and violence.","whyEl":"Η αντιμετώπιση της ρητορικής μίσους συμβάλλει στην πρόληψη των διακρίσεων και της βίας."}],"06-19":[{"en":"International Day for the Elimination of Sexual Violence in Conflict","el":"Διεθνής Ημέρα Εξάλειψης της Σεξουαλικής Βίας σε Συγκρούσεις","whyEn":"Survivors deserve protection, justice and lasting support.","whyEl":"Οι επιζώντες και οι επιζώσες χρειάζονται προστασία, δικαιοσύνη και διαρκή στήριξη."}],"06-20":[{"en":"World Refugee Day","el":"Παγκόσμια Ημέρα Προσφύγων","whyEn":"People forced to flee deserve safety, dignity and a chance to rebuild their lives.","whyEl":"Όσοι αναγκάζονται να εγκαταλείψουν τον τόπο τους αξίζουν ασφάλεια, αξιοπρέπεια και ευκαιρία να ξαναχτίσουν τη ζωή τους."}],"06-21":[{"en":"International Day of Yoga","el":"Διεθνής Ημέρα Γιόγκα","whyEn":"Accessible physical activity and mindful movement can support well-being.","whyEl":"Η προσιτή σωματική δραστηριότητα και η συνειδητή κίνηση μπορούν να ενισχύσουν την ευεξία."}],"06-23":[{"en":"United Nations Public Service Day","el":"Ημέρα Δημόσιας Υπηρεσίας των Ηνωμένων Εθνών","whyEn":"Effective public services underpin health, education and equal access to rights.","whyEl":"Οι αποτελεσματικές δημόσιες υπηρεσίες στηρίζουν την υγεία, την εκπαίδευση και την ισότιμη πρόσβαση στα δικαιώματα."}],"06-26":[{"en":"United Nations International Day in Support of Victims of Torture","el":"Διεθνής Ημέρα Στήριξης των Θυμάτων Βασανιστηρίων","whyEn":"Torture is never acceptable; survivors need care and accountability.","whyEl":"Τα βασανιστήρια δεν δικαιολογούνται ποτέ· τα θύματα χρειάζονται φροντίδα και απόδοση ευθυνών."}],"06-27":[{"en":"Micro-, Small and Medium-sized Enterprises Day","el":"Ημέρα Μικρών και Μεσαίων Επιχειρήσεων","whyEn":"Small businesses create jobs, serve local needs and support livelihoods.","whyEl":"Οι μικρές επιχειρήσεις δημιουργούν θέσεις εργασίας, καλύπτουν τοπικές ανάγκες και στηρίζουν τα εισοδήματα."}],"06-30":[{"en":"International Asteroid Day","el":"Διεθνής Ημέρα Αστεροειδών","whyEn":"Studying asteroids helps scientists understand our solar system and planetary risks.","whyEl":"Η μελέτη των αστεροειδών βοηθά στην κατανόηση του ηλιακού συστήματος και των πλανητικών κινδύνων."}],"07-06":[{"en":"World Rural Development Day","el":"Παγκόσμια Ημέρα Αγροτικής Ανάπτυξης","whyEn":"Thriving rural communities strengthen food systems and reduce regional inequalities.","whyEl":"Οι ζωντανές αγροτικές κοινότητες στηρίζουν τη διατροφή και περιορίζουν τις περιφερειακές ανισότητες."}],"07-07":[{"en":"World Kiswahili Language Day","el":"Παγκόσμια Ημέρα Σουαχίλι","whyEn":"Languages connect communities and carry knowledge across generations.","whyEl":"Οι γλώσσες συνδέουν κοινωνίες και μεταφέρουν γνώση από γενιά σε γενιά."}],"07-11":[{"en":"World Population Day","el":"Παγκόσμια Ημέρα Πληθυσμού","whyEn":"Understanding demographic change helps societies plan fair services and opportunities.","whyEl":"Η κατανόηση των δημογραφικών αλλαγών βοηθά στον δίκαιο σχεδιασμό υπηρεσιών και ευκαιριών."}],"07-15":[{"en":"World Youth Skills Day","el":"Παγκόσμια Ημέρα Δεξιοτήτων των Νέων","whyEn":"Skills training helps young people enter work and adapt to changing economies.","whyEl":"Η ανάπτυξη δεξιοτήτων βοηθά τους νέους στην εργασία και στις αλλαγές της οικονομίας."}],"07-18":[{"en":"Nelson Mandela International Day","el":"Διεθνής Ημέρα Νέλσον Μαντέλα","whyEn":"Mandela's legacy reminds us of the importance of dignity, equality and reconciliation.","whyEl":"Η παρακαταθήκη του Μαντέλα θυμίζει την αξία της αξιοπρέπειας, της ισότητας και της συμφιλίωσης."}],"07-20":[{"en":"World Chess Day","el":"Παγκόσμια Ημέρα Σκακιού","whyEn":"Chess encourages strategic thinking, patience and connection across generations.","whyEl":"Το σκάκι καλλιεργεί στρατηγική σκέψη, υπομονή και επικοινωνία ανάμεσα στις γενιές."}],"07-25":[{"en":"World Drowning Prevention Day","el":"Παγκόσμια Ημέρα Πρόληψης Πνιγμών","whyEn":"Swimming skills, supervision and water safety measures can save lives.","whyEl":"Η εκμάθηση κολύμβησης, η επίβλεψη και τα μέτρα ασφάλειας στο νερό σώζουν ζωές."}],"07-28":[{"en":"World Hepatitis Day","el":"Παγκόσμια Ημέρα Ηπατίτιδας","whyEn":"Vaccination, testing and treatment can prevent serious liver disease.","whyEl":"Ο εμβολιασμός, ο έλεγχος και η θεραπεία προλαμβάνουν σοβαρές παθήσεις του ήπατος."}],"07-30":[{"en":"World Day against Trafficking in Persons","el":"Παγκόσμια Ημέρα κατά της Εμπορίας Ανθρώπων","whyEn":"Preventing trafficking protects people from exploitation and upholds human dignity.","whyEl":"Η πρόληψη της εμπορίας ανθρώπων προστατεύει από την εκμετάλλευση και υπερασπίζεται την ανθρώπινη αξιοπρέπεια."}],"08-09":[{"en":"International Day of the World's Indigenous Peoples","el":"Διεθνής Ημέρα Αυτοχθόνων Λαών","whyEn":"Indigenous communities' rights and knowledge are vital to cultural and environmental diversity.","whyEl":"Τα δικαιώματα και η γνώση των αυτοχθόνων λαών είναι σημαντικά για την πολιτιστική και περιβαλλοντική ποικιλία."}],"08-12":[{"en":"International Youth Day","el":"Διεθνής Ημέρα Νεολαίας","whyEn":"Young people's voices matter in decisions shaping tomorrow's world.","whyEl":"Οι φωνές των νέων έχουν σημασία στις αποφάσεις που διαμορφώνουν το αύριο."}],"08-19":[{"en":"World Humanitarian Day","el":"Παγκόσμια Ημέρα Ανθρωπιστικής Δράσης","whyEn":"Humanitarian workers and volunteers help people survive crises and disasters.","whyEl":"Οι εργαζόμενοι και οι εθελοντές της ανθρωπιστικής δράσης βοηθούν ανθρώπους σε κρίσεις και καταστροφές."}],"08-21":[{"en":"International Day of Remembrance and Tribute to the Victims of Terrorism","el":"Διεθνής Ημέρα Μνήμης των Θυμάτων Τρομοκρατίας","whyEn":"Victims and survivors deserve remembrance, support and justice.","whyEl":"Τα θύματα και οι επιζώντες της τρομοκρατίας αξίζουν μνήμη, στήριξη και δικαιοσύνη."}],"08-23":[{"en":"International Day for the Remembrance of the Slave Trade and Its Abolition","el":"Διεθνής Ημέρα Μνήμης του Δουλεμπορίου και της Κατάργησής του","whyEn":"Learning this history helps confront racism and honor those who resisted slavery.","whyEl":"Η γνώση αυτής της ιστορίας βοηθά στην αντιμετώπιση του ρατσισμού και τιμά όσους αντιστάθηκαν στη δουλεία."}],"08-27":[{"en":"World Lake Day","el":"Παγκόσμια Ημέρα Λιμνών","whyEn":"Lakes provide freshwater, wildlife habitats and resources for local communities.","whyEl":"Οι λίμνες προσφέρουν γλυκό νερό, βιότοπους και σημαντικούς πόρους για τις τοπικές κοινωνίες."}],"08-29":[{"en":"International Day against Nuclear Tests","el":"Διεθνής Ημέρα κατά των Πυρηνικών Δοκιμών","whyEn":"Ending nuclear testing protects people, ecosystems and future generations.","whyEl":"Ο τερματισμός των πυρηνικών δοκιμών προστατεύει ανθρώπους, οικοσυστήματα και μελλοντικές γενιές."}],"08-30":[{"en":"International Day of the Victims of Enforced Disappearances","el":"Διεθνής Ημέρα Θυμάτων Αναγκαστικών Εξαφανίσεων","whyEn":"Families deserve truth and accountability when loved ones disappear forcibly.","whyEl":"Οι οικογένειες δικαιούνται αλήθεια και λογοδοσία όταν αγαπημένα τους πρόσωπα εξαφανίζονται βίαια."}],"09-05":[{"en":"International Day of Charity","el":"Διεθνής Ημέρα Φιλανθρωπίας","whyEn":"Acts of solidarity can help communities respond to hardship and inequality.","whyEl":"Οι πράξεις αλληλεγγύης βοηθούν τις κοινότητες να αντιμετωπίζουν δυσκολίες και ανισότητες."}],"09-07":[{"en":"International Day of Clean Air for Blue Skies","el":"Διεθνής Ημέρα Καθαρού Αέρα","whyEn":"Cleaner air protects health and makes cities safer to live in.","whyEl":"Ο καθαρότερος αέρας προστατεύει την υγεία και κάνει τις πόλεις ασφαλέστερες."}],"09-08":[{"en":"International Literacy Day","el":"Διεθνής Ημέρα Γραμματισμού","whyEn":"Literacy is essential for learning, participation and independent decision-making.","whyEl":"Ο γραμματισμός είναι απαραίτητος για τη μάθηση, τη συμμετοχή και τις ανεξάρτητες αποφάσεις."}],"09-09":[{"en":"International Day to Protect Education from Attack","el":"Διεθνής Ημέρα Προστασίας της Εκπαίδευσης από Επιθέσεις","whyEn":"Students and teachers must be able to learn and teach safely, even during conflict.","whyEl":"Οι μαθητές και οι εκπαιδευτικοί πρέπει να μαθαίνουν και να διδάσκουν με ασφάλεια, ακόμη και σε συγκρούσεις."}],"09-15":[{"en":"International Day of Democracy","el":"Διεθνής Ημέρα Δημοκρατίας","whyEn":"Participation, accountability and fundamental rights keep democracy meaningful.","whyEl":"Η συμμετοχή, η λογοδοσία και τα θεμελιώδη δικαιώματα δίνουν ουσία στη δημοκρατία."}],"09-16":[{"en":"International Day for the Preservation of the Ozone Layer","el":"Διεθνής Ημέρα Προστασίας της Στιβάδας του Όζοντος","whyEn":"Global cooperation to protect ozone shows that environmental damage can be reversed.","whyEl":"Η διεθνής συνεργασία για το όζον δείχνει ότι η περιβαλλοντική ζημιά μπορεί να αντιμετωπιστεί."}],"09-17":[{"en":"World Patient Safety Day","el":"Παγκόσμια Ημέρα Ασφάλειας Ασθενών","whyEn":"Safer healthcare reduces preventable harm and builds trust.","whyEl":"Η ασφαλέστερη περίθαλψη μειώνει βλάβες που μπορούν να αποφευχθούν και ενισχύει την εμπιστοσύνη."}],"09-18":[{"en":"International Equal Pay Day","el":"Διεθνής Ημέρα Ίσης Αμοιβής","whyEn":"Equal pay for work of equal value is a basic part of workplace fairness.","whyEl":"Η ίση αμοιβή για εργασία ίσης αξίας αποτελεί βασικό στοιχείο δικαιοσύνης στην εργασία."}],"09-20":[{"en":"World Cleanup Day","el":"Παγκόσμια Ημέρα Καθαρισμού","whyEn":"Community cleanups can reduce litter and encourage lasting waste prevention.","whyEl":"Οι συλλογικοί καθαρισμοί μειώνουν τα απορρίμματα και ενθαρρύνουν την πρόληψη δημιουργίας τους."}],"09-21":[{"en":"International Day of Peace","el":"Διεθνής Ημέρα Ειρήνης","whyEn":"Peace requires dialogue, trust and efforts to prevent violence.","whyEl":"Η ειρήνη απαιτεί διάλογο, εμπιστοσύνη και προσπάθεια πρόληψης της βίας."}],"09-23":[{"en":"International Day of Sign Languages","el":"Διεθνής Ημέρα Νοηματικών Γλωσσών","whyEn":"Sign languages support communication, identity and equal access for deaf people.","whyEl":"Οι νοηματικές γλώσσες στηρίζουν την επικοινωνία, την ταυτότητα και την ισότιμη πρόσβαση των κωφών ανθρώπων."}],"09-26":[{"en":"International Day for the Total Elimination of Nuclear Weapons","el":"Διεθνής Ημέρα για την Πλήρη Εξάλειψη των Πυρηνικών Όπλων","whyEn":"Nuclear disarmament reduces the risk of catastrophic human suffering.","whyEl":"Ο πυρηνικός αφοπλισμός μειώνει τον κίνδυνο καταστροφικού ανθρώπινου πόνου."}],"09-27":[{"en":"World Tourism Day","el":"Παγκόσμια Ημέρα Τουρισμού","whyEn":"Responsible tourism can support communities while respecting culture and nature.","whyEl":"Ο υπεύθυνος τουρισμός στηρίζει τις τοπικές κοινωνίες με σεβασμό στον πολιτισμό και στη φύση."}],"09-28":[{"en":"International Day for Universal Access to Information","el":"Διεθνής Ημέρα Καθολικής Πρόσβασης στην Πληροφόρηση","whyEn":"Access to reliable information supports transparency and informed choices.","whyEl":"Η πρόσβαση σε αξιόπιστη πληροφόρηση στηρίζει τη διαφάνεια και τις τεκμηριωμένες επιλογές."}],"09-29":[{"en":"International Day of Awareness of Food Loss and Waste","el":"Διεθνής Ημέρα Ευαισθητοποίησης για την Απώλεια και τη Σπατάλη Τροφίμων","whyEn":"Wasting less food saves resources and can improve food security.","whyEl":"Η μείωση της σπατάλης τροφίμων εξοικονομεί πόρους και ενισχύει την επισιτιστική ασφάλεια."}],"09-30":[{"en":"International Translation Day","el":"Διεθνής Ημέρα Μετάφρασης","whyEn":"Translation helps people exchange knowledge across languages and cultures.","whyEl":"Η μετάφραση επιτρέπει την ανταλλαγή γνώσης ανάμεσα σε γλώσσες και πολιτισμούς."}],"10-01":[{"en":"International Day of Older Persons","el":"Διεθνής Ημέρα Ηλικιωμένων","whyEn":"Older people deserve dignity, participation and accessible care.","whyEl":"Οι ηλικιωμένοι δικαιούνται αξιοπρέπεια, συμμετοχή και προσβάσιμη φροντίδα."}],"10-02":[{"en":"International Day of Non-Violence","el":"Διεθνής Ημέρα Μη Βίας","whyEn":"Non-violent action reminds us that change need not rely on harm.","whyEl":"Η μη βίαιη δράση θυμίζει ότι η αλλαγή δεν χρειάζεται να βασίζεται στη βία."}],"10-05":[{"en":"World Teachers' Day","el":"Παγκόσμια Ημέρα Εκπαιδευτικών","whyEn":"Teachers shape learning and opportunity; their work deserves support and respect.","whyEl":"Οι εκπαιδευτικοί διαμορφώνουν τη μάθηση και τις ευκαιρίες· το έργο τους αξίζει στήριξη και σεβασμό."}],"10-09":[{"en":"World Post Day","el":"Παγκόσμια Ημέρα Ταχυδρομείων","whyEn":"Postal services connect people and businesses, including remote communities.","whyEl":"Οι ταχυδρομικές υπηρεσίες συνδέουν ανθρώπους και επιχειρήσεις, ακόμη και σε απομακρυσμένες περιοχές."}],"10-10":[{"en":"World Mental Health Day","el":"Παγκόσμια Ημέρα Ψυχικής Υγείας","whyEn":"Access to mental healthcare and freedom from stigma matter to everyone's well-being.","whyEl":"Η πρόσβαση στη φροντίδα ψυχικής υγείας και η καταπολέμηση του στίγματος αφορούν όλους."}],"10-11":[{"en":"International Day of the Girl Child","el":"Διεθνής Ημέρα Κοριτσιού","whyEn":"Girls need safety, education and equal chances to shape their futures.","whyEl":"Τα κορίτσια χρειάζονται ασφάλεια, εκπαίδευση και ίσες ευκαιρίες να διαμορφώσουν το μέλλον τους."}],"10-13":[{"en":"International Day for Disaster Risk Reduction","el":"Διεθνής Ημέρα Μείωσης Κινδύνου Καταστροφών","whyEn":"Prepared communities can reduce losses from fires, floods and earthquakes.","whyEl":"Οι προετοιμασμένες κοινωνίες μπορούν να περιορίσουν τις απώλειες από πυρκαγιές, πλημμύρες και σεισμούς."}],"10-15":[{"en":"International Day of Rural Women","el":"Διεθνής Ημέρα Γυναικών της Υπαίθρου","whyEn":"Rural women are central to food production and community life, yet often face unequal opportunities.","whyEl":"Οι γυναίκες της υπαίθρου στηρίζουν την παραγωγή τροφής και τις κοινότητες, αλλά συχνά αντιμετωπίζουν ανισότητες."}],"10-16":[{"en":"World Food Day","el":"Παγκόσμια Ημέρα Διατροφής","whyEn":"Everyone should have access to sufficient, nutritious and affordable food.","whyEl":"Όλοι πρέπει να έχουν πρόσβαση σε επαρκή, θρεπτική και προσιτή τροφή."}],"10-17":[{"en":"International Day for the Eradication of Poverty","el":"Διεθνής Ημέρα Εξάλειψης της Φτώχειας","whyEn":"Reducing poverty requires opportunities, protection and respect for human dignity.","whyEl":"Η μείωση της φτώχειας απαιτεί ευκαιρίες, κοινωνική προστασία και σεβασμό στην αξιοπρέπεια."}],"10-24":[{"en":"United Nations Day","el":"Ημέρα Ηνωμένων Εθνών","whyEn":"International cooperation matters when challenges cross borders.","whyEl":"Η διεθνής συνεργασία είναι ουσιαστική όταν οι προκλήσεις ξεπερνούν τα σύνορα."}],"10-27":[{"en":"World Day for Audiovisual Heritage","el":"Παγκόσμια Ημέρα Οπτικοακουστικής Κληρονομιάς","whyEn":"Preserving recordings and film safeguards memory, language and culture.","whyEl":"Η διατήρηση ηχογραφήσεων και ταινιών προστατεύει τη μνήμη, τη γλώσσα και τον πολιτισμό."}],"10-29":[{"en":"International Day of Care and Support","el":"Διεθνής Ημέρα Φροντίδας και Υποστήριξης","whyEn":"Care work sustains families and communities and deserves recognition and fair support.","whyEl":"Η εργασία φροντίδας στηρίζει οικογένειες και κοινωνίες και αξίζει αναγνώριση και δίκαιη υποστήριξη."}],"10-31":[{"en":"World Cities Day","el":"Παγκόσμια Ημέρα Πόλεων","whyEn":"Better urban design can improve housing, mobility, air quality and accessibility.","whyEl":"Ο καλύτερος αστικός σχεδιασμός μπορεί να βελτιώσει τη στέγαση, τις μετακινήσεις, τον αέρα και την προσβασιμότητα."}],"11-02":[{"en":"International Day to End Impunity for Crimes against Journalists","el":"Διεθνής Ημέρα Τερματισμού της Ατιμωρησίας για Εγκλήματα κατά Δημοσιογράφων","whyEn":"Protecting journalists protects the public's right to know.","whyEl":"Η προστασία των δημοσιογράφων προστατεύει το δικαίωμα όλων στην ενημέρωση."}],"11-03":[{"en":"International Day for Biosphere Reserves","el":"Διεθνής Ημέρα Αποθεμάτων Βιόσφαιρας","whyEn":"Biosphere reserves show how people and nature can thrive together.","whyEl":"Τα αποθέματα βιόσφαιρας δείχνουν πώς άνθρωποι και φύση μπορούν να ευημερούν μαζί."}],"11-05":[{"en":"World Tsunami Awareness Day","el":"Παγκόσμια Ημέρα Ενημέρωσης για τα Τσουνάμι","whyEn":"Early warnings and public preparedness can save lives along coastlines.","whyEl":"Η έγκαιρη προειδοποίηση και η προετοιμασία του κοινού μπορούν να σώσουν ζωές στις παράκτιες περιοχές."}],"11-06":[{"en":"International Day for Preventing the Exploitation of the Environment in War and Armed Conflict","el":"Διεθνής Ημέρα Προστασίας του Περιβάλλοντος σε Πόλεμο και Ένοπλες Συγκρούσεις","whyEn":"Conflict damages land, water and livelihoods long after weapons fall silent.","whyEl":"Οι συγκρούσεις καταστρέφουν τη γη, το νερό και τα μέσα διαβίωσης πολύ μετά τη σιγή των όπλων."}],"11-10":[{"en":"World Science Day for Peace and Development","el":"Παγκόσμια Ημέρα Επιστήμης για την Ειρήνη και την Ανάπτυξη","whyEn":"Science can advance health, sustainability and cooperation when knowledge is shared.","whyEl":"Η επιστήμη προάγει την υγεία, τη βιωσιμότητα και τη συνεργασία όταν η γνώση μοιράζεται."}],"11-14":[{"en":"World Diabetes Day","el":"Παγκόσμια Ημέρα Διαβήτη","whyEn":"Awareness, diagnosis and treatment reduce complications and support healthier lives.","whyEl":"Η ενημέρωση, η διάγνωση και η θεραπεία μειώνουν τις επιπλοκές και στηρίζουν την υγεία."}],"11-16":[{"en":"International Day for Tolerance","el":"Διεθνής Ημέρα Ανεκτικότητας","whyEn":"Listening across differences helps prevent prejudice and conflict.","whyEl":"Η ακρόαση και ο σεβασμός των διαφορών βοηθούν στην πρόληψη προκαταλήψεων και συγκρούσεων."}],"11-19":[{"en":"World Toilet Day","el":"Παγκόσμια Ημέρα Τουαλέτας","whyEn":"Safe sanitation prevents disease and protects dignity.","whyEl":"Η ασφαλής αποχέτευση προλαμβάνει ασθένειες και προστατεύει την ανθρώπινη αξιοπρέπεια."}],"11-20":[{"en":"World Children's Day","el":"Παγκόσμια Ημέρα Παιδιού","whyEn":"Children's rights to safety, learning and participation must be protected everywhere.","whyEl":"Τα δικαιώματα των παιδιών στην ασφάλεια, στη μάθηση και στη συμμετοχή πρέπει να προστατεύονται παντού."}],"11-21":[{"en":"World Television Day","el":"Παγκόσμια Ημέρα Τηλεόρασης","whyEn":"Television can inform, educate and connect audiences around shared experiences.","whyEl":"Η τηλεόραση μπορεί να ενημερώνει, να εκπαιδεύει και να συνδέει το κοινό μέσα από κοινές εμπειρίες."}],"11-25":[{"en":"International Day for the Elimination of Violence against Women","el":"Διεθνής Ημέρα Εξάλειψης της Βίας κατά των Γυναικών","whyEn":"Preventing violence and supporting survivors are essential to safety and equality.","whyEl":"Η πρόληψη της βίας και η στήριξη των επιζωσών είναι απαραίτητες για την ασφάλεια και την ισότητα."}],"11-26":[{"en":"World Sustainable Transport Day","el":"Παγκόσμια Ημέρα Βιώσιμων Μεταφορών","whyEn":"Accessible, lower-emission transport can make communities healthier and fairer.","whyEl":"Οι προσβάσιμες μεταφορές με λιγότερες εκπομπές κάνουν τις κοινωνίες υγιέστερες και δικαιότερες."}],"11-29":[{"en":"International Day of Solidarity with the Palestinian People","el":"Διεθνής Ημέρα Αλληλεγγύης προς τον Παλαιστινιακό Λαό","whyEn":"The observance encourages attention to the rights, dignity and peaceful future of Palestinians.","whyEl":"Η ημέρα στρέφει την προσοχή στα δικαιώματα, την αξιοπρέπεια και ένα ειρηνικό μέλλον για τους Παλαιστινίους."}],"12-01":[{"en":"World AIDS Day","el":"Παγκόσμια Ημέρα κατά του AIDS","whyEn":"Testing, treatment and freedom from stigma help prevent HIV transmission and improve lives.","whyEl":"Ο έλεγχος, η θεραπεία και η αντιμετώπιση του στίγματος προλαμβάνουν τη μετάδοση του HIV και βελτιώνουν τη ζωή."}],"12-02":[{"en":"International Day for the Abolition of Slavery","el":"Διεθνής Ημέρα Κατάργησης της Δουλείας","whyEn":"Modern slavery and forced labour still demand protection, prevention and justice.","whyEl":"Η σύγχρονη δουλεία και η καταναγκαστική εργασία απαιτούν προστασία, πρόληψη και δικαιοσύνη."}],"12-03":[{"en":"International Day of Persons with Disabilities","el":"Διεθνής Ημέρα Ατόμων με Αναπηρία","whyEn":"Removing barriers to access and participation benefits everyone.","whyEl":"Η άρση των εμποδίων στην πρόσβαση και τη συμμετοχή ωφελεί ολόκληρη την κοινωνία."}],"12-05":[{"en":"International Volunteer Day","el":"Διεθνής Ημέρα Εθελοντισμού","whyEn":"Volunteers bring practical help and solidarity where communities need them.","whyEl":"Οι εθελοντές προσφέρουν ουσιαστική βοήθεια και αλληλεγγύη όπου υπάρχει ανάγκη."},{"en":"World Soil Day","el":"Παγκόσμια Ημέρα Εδάφους","whyEn":"Healthy soil supports food, biodiversity and climate resilience.","whyEl":"Το υγιές έδαφος στηρίζει την παραγωγή τροφής, τη βιοποικιλότητα και την ανθεκτικότητα στο κλίμα."}],"12-09":[{"en":"International Anti-Corruption Day","el":"Διεθνής Ημέρα κατά της Διαφθοράς","whyEn":"Transparency and accountability protect public trust and shared resources.","whyEl":"Η διαφάνεια και η λογοδοσία προστατεύουν την εμπιστοσύνη και τους κοινούς πόρους."}],"12-10":[{"en":"Human Rights Day","el":"Ημέρα Ανθρωπίνων Δικαιωμάτων","whyEn":"Human rights belong to every person and must be protected in everyday life.","whyEl":"Τα ανθρώπινα δικαιώματα ανήκουν σε κάθε άνθρωπο και πρέπει να προστατεύονται στην καθημερινότητα."}],"12-11":[{"en":"International Mountain Day","el":"Διεθνής Ημέρα Βουνού","whyEn":"Mountains provide water, wildlife habitats and livelihoods, but face increasing pressures.","whyEl":"Τα βουνά προσφέρουν νερό, βιότοπους και μέσα διαβίωσης, αλλά δέχονται αυξανόμενες πιέσεις."}],"12-12":[{"en":"International Universal Health Coverage Day","el":"Διεθνής Ημέρα Καθολικής Υγειονομικής Κάλυψης","whyEn":"Everyone should be able to access essential healthcare without financial hardship.","whyEl":"Όλοι πρέπει να έχουν πρόσβαση στη βασική περίθαλψη χωρίς οικονομική εξουθένωση."}],"12-18":[{"en":"International Migrants Day","el":"Διεθνής Ημέρα Μεταναστών","whyEn":"Migrants contribute to communities and deserve safety, rights and fair treatment.","whyEl":"Οι μετανάστες συμβάλλουν στις κοινωνίες και αξίζουν ασφάλεια, δικαιώματα και δίκαιη μεταχείριση."}],"12-20":[{"en":"International Human Solidarity Day","el":"Διεθνής Ημέρα Ανθρώπινης Αλληλεγγύης","whyEn":"Shared challenges are easier to face when people and nations support one another.","whyEl":"Οι κοινές προκλήσεις αντιμετωπίζονται ευκολότερα όταν άνθρωποι και κράτη αλληλοστηρίζονται."}],"12-21":[{"en":"World Meditation Day","el":"Παγκόσμια Ημέρα Διαλογισμού","whyEn":"Quiet reflection can support attention and emotional well-being for some people.","whyEl":"Η ήρεμη ενδοσκόπηση μπορεί να στηρίξει την προσοχή και τη συναισθηματική ευεξία ορισμένων ανθρώπων."}],"12-27":[{"en":"International Day of Epidemic Preparedness","el":"Διεθνής Ημέρα Ετοιμότητας για Επιδημίες","whyEn":"Prepared health systems and trusted information help communities respond to outbreaks.","whyEl":"Τα προετοιμασμένα συστήματα υγείας και η αξιόπιστη ενημέρωση βοηθούν στην αντιμετώπιση επιδημιών."}]};

  var NAMEDAY_DURATION_MS = 5000;
