      '.swai-welcome-today-meta{margin-top:13px;font:800 11px/1.35 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:.09em;color:#746c60;text-transform:uppercase}',
