      '@media(max-width:520px){.swai-welcome-overlay{padding:15px}.swai-welcome-card{width:100%;border-radius:20px;padding:25px 20px 23px}.swai-welcome-kicker{font-size:10px;margin-bottom:12px}.swai-welcome-author{font-size:13px}.swai-welcome-today-text{font-size:14px}.swai-welcome-actions{margin-top:15px}}',
